/**
 * 开放 API 参考模板（从 console.whaleal.com/developers/api/* 迁移，2026-11-28）。
 *
 * 由 gatsby-node.js 的 createPages 从 src/data/apiDocs.js 生成：
 *   /developers/api/                    概览（Overview）
 *   /developers/api/<path>/             各端点页（send/status/usage/...）
 * 每页 10 语路由，正文语言由 pageContext.locale 决定，与 blog/help 同构。
 *
 * 🔴 正文 10 语来自数据文件（console 的 zh/en 精翻 + PUBLIC_TRANS 展开），
 *    本模板零硬编码文案翻译；代码块/表格数据行按 console 判据原样输出。
 * 🔴 BSP §6：1.5 落地后红线收窄为「以实际端点为准」——本页描述真实
 *    /open/v1/** 行为（含 channel 参数），不是营销场景的「一个 API 对接三渠道」。
 *
 * @since 2026-11-28
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { API_DOCS } from '../data/apiDocs';
import { MESSAGING_PRODUCT_NAME } from '../constants/brand';
import '../styles/marketing.css';
import { usePageI18n } from '../i18n';
import { localePath } from '../i18n/config';

const { GROUPS, PAGES } = API_DOCS;

const CJK = new Set(['zh', 'zh-Hant']);
const platformName = (lang) => (CJK.has(lang) ? '鲸联' : MESSAGING_PRODUCT_NAME);

/** 按语言取多语字段，缺该语回退英文（英文是契约真源）。 */
function pick(v, lang) {
  if (!v) return '';
  return v[lang] || v.en || '';
}

const UI = {
  developers: {
    en: 'Developers', zh: '开发者', de: 'Entwickler', fr: 'Développeurs', es: 'Desarrolladores',
    ja: '開発者', it: 'Sviluppatori', pt: 'Desenvolvedores', ko: '개발자', 'zh-Hant': '開發者',
  },
  apiRef: {
    en: 'API reference', zh: 'API 参考', de: 'API-Referenz', fr: 'Référence API', es: 'Referencia API',
    ja: 'API リファレンス', it: 'Guida API', pt: 'Referência da API', ko: 'API 참조', 'zh-Hant': 'API 參考',
  },
  home: {
    en: 'Home', zh: '首页', de: 'Startseite', fr: 'Accueil', es: 'Inicio', ja: 'ホーム',
    it: 'Home', pt: 'Início', ko: '홈', 'zh-Hant': '首頁',
  },
  overview: {
    en: 'Overview', zh: '概览', de: 'Überblick', fr: 'Aperçu', es: 'Resumen', ja: '概要',
    it: 'Panoramica', pt: 'Visão geral', ko: '개요', 'zh-Hant': '總覽',
  },
  prev: {
    en: 'Previous', zh: '上一页', de: 'Zurück', fr: 'Précédent', es: 'Anterior', ja: '前へ',
    it: 'Precedente', pt: 'Anterior', ko: '이전', 'zh-Hant': '上一頁',
  },
  next: {
    en: 'Next', zh: '下一页', de: 'Weiter', fr: 'Suivant', es: 'Siguiente', ja: '次へ',
    it: 'Successivo', pt: 'Próximo', ko: '다음', 'zh-Hant': '下一頁',
  },
  desc: {
    en: 'Endpoint-level reference for the Whaleal open API: authentication, request fields, response codes, rate limits and status callbacks.',
    zh: 'Whaleal 开放 API 的端点级参考：鉴权、请求字段、响应码、限速与状态回调。',
    de: 'Referenz auf Endpunkt-Ebene für die Whaleal Open API: Authentifizierung, Anfragefelder, Antwortcodes, Ratenlimits und Status-Callbacks.',
    fr: 'Référence par point d’accès de l’API ouverte Whaleal : authentification, champs de requête, codes de réponse, limites de débit et rappels de statut.',
    es: 'Referencia por endpoint de la API abierta de Whaleal: autenticación, campos de solicitud, códigos de respuesta, límites de velocidad y devoluciones de estado.',
    ja: 'Whaleal オープン API のエンドポイント別リファレンス：認証、リクエスト項目、レスポンスコード、レート制限、ステータスコールバック。',
    it: 'Guida per endpoint alle API aperte Whaleal: autenticazione, campi di richiesta, codici di risposta, limiti di velocità e callback di stato.',
    pt: 'Referência por endpoint da API aberta Whaleal: autenticação, campos de solicitação, códigos de resposta, limites de taxa e callbacks de status.',
    ko: 'Whaleal 오픈 API의 엔드포인트별 레퍼런스: 인증, 요청 필드, 응답 코드, 속도 제한 및 상태 콜백.',
    'zh-Hant': 'Whaleal 開放 API 的端點級參考：身份驗證、請求欄位、回應碼、限速與狀態回呼。',
  },
};

function apiHref(page, lang) {
  return localePath(page.path ? `/developers/api/${page.path}/` : '/developers/api/', lang);
}

function Block({ block, lang }) {
  if (block.kind === 'code') {
    return (
      <pre className="mk-code" tabIndex={0}><code>{block.text}</code></pre>
    );
  }
  if (block.kind === 'table') {
    const head = pick(block.head, lang) || [];
    // 🔴 rows 与 head 同为多语字典，必须按 lang 取值（2026-11-28 修复）。
    //    此前写 block.rows 会把 {en,zh,...} 当行数组遍历 ⇒ 页面渲染错位。
    const rows = pick(block.rows, lang) || [];
    return (
      <div className="mk-table-wrap" tabIndex={0}>
        <table className="mk-table">
          <thead><tr>{head.map((h, i) => <th key={i}>{h}</th>)}</tr></thead>
          <tbody>
            {rows.map((row, ri) => (
              <tr key={ri}>{row.map((cell, ci) => <td key={ci}>{cell}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }
  if (block.kind === 'note') {
    return <div className="mk-note"><p>{pick(block.text, lang)}</p></div>;
  }
  return <p className="mk-section-lead">{pick(block.text, lang)}</p>;
}

export default function ApiDocPage({ pageContext }) {
  const { locale } = usePageI18n(pageContext);
  const lang = locale || 'en';
  const page = PAGES.find((p) => p.id === pageContext.pageId) || PAGES[0];
  const idx = PAGES.findIndex((p) => p.id === page.id);
  const prev = idx > 0 ? PAGES[idx - 1] : null;
  const next = idx < PAGES.length - 1 ? PAGES[idx + 1] : null;
  const pagePath = apiHref(page, lang);
  const title = `${pick(page.title, lang)} — ${pick(UI.apiRef, lang)} | ${platformName(lang)}`;

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title={title}
        description={pick(UI.desc, lang)}
        pathname={page.path ? `/developers/api/${page.path}/` : '/developers/api/'}
        canonicalPath={pagePath}
        softwareApp={false}
        breadcrumbs={[
          { name: pick(UI.home, lang), path: localePath('/', lang) },
          // 没有 /developers/ 索引页 —— 不造死链，直接从首页跳到 API 概览。
          { name: pick(UI.apiRef, lang), path: localePath('/developers/api/', lang) },
          ...(page.path ? [{ name: pick(page.title, lang), path: pagePath }] : []),
        ]}
        hrefLang={lang}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{pick(UI.apiRef, lang)}</span>
          <h1>{pick(page.title, lang)}</h1>
          <p className="mk-lead">{pick(UI.desc, lang)}</p>
        </header>

        <div className="mk-grid">
          <nav className="mk-card" aria-label={pick(UI.apiRef, lang)}>
            <h2>{pick(UI.apiRef, lang)}</h2>
            {GROUPS.map((group) => (
              <div key={group.id}>
                <h3>{pick(group.title, lang)}</h3>
                <ul className="mk-list">
                  {PAGES.filter((p) => p.group === group.id).map((p) => (
                    <li key={p.id}>
                      {p.id === page.id
                        ? <strong>{pick(p.title, lang)}</strong>
                        : <Link to={apiHref(p, lang)}>{pick(p.title, lang)}</Link>}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>

          <article className="mk-section">
            {page.sections.map((section) => (
              <section key={section.id}>
                <h2>{pick(section.title, lang)}</h2>
                {section.blocks.map((block, i) => <Block key={i} block={block} lang={lang} />)}
              </section>
            ))}

            <div className="mk-actions">
              {prev && <Link className="mk-btn mk-btn-secondary" to={apiHref(prev, lang)}>
                ← {pick(UI.prev, lang)}：{pick(prev.title, lang)}
              </Link>}
              {next && <Link className="mk-btn mk-btn-secondary" to={apiHref(next, lang)}>
                {pick(UI.next, lang)}：{pick(next.title, lang)} →
              </Link>}
            </div>
          </article>
        </div>
      </div>
    </Layout>
  );
}
